// nextcuda video studio (nextcuda video serve): the routes' types and a typed client.
// Generated by rpcgen from the #[route] handlers: do not edit; regenerate.
/* eslint-disable */

/** A batch of a project's queued clips */
export interface Batch {
  batch: string;
  clips: number;
  video_s: number;
  paused: boolean;
}

/** A canvas the table offers, with its price against 640x480 */
export interface Canvas {
  width: number;
  height: number;
  aspect: string;
  note: string;
  mpx: number;
  cost: number;
  default: boolean;
}

/** The canvases */
export interface Canvases {
  canvases: Canvas[];
}

/** Chaining a clip onto another: what `chain` sets (guide_clip, first_audio(_s), first_frame, chain_mode, exposure_ref; a flat key of the request wins) */
export interface Chain {
  /** the clip it follows: an anchor (prev, prev_cam, first, first_cam) or a clip's name (default prev) */
  from?: string | null;
  /** 0 or 17k + 5: the last N frames as a moving keyframe at frame 0 (trim N/2 each side when joining) */
  context_frames?: number | null;
  /** with context_frames: the last N/24 s of sound too (default true) */
  sound?: boolean | null;
  /** from's last frame as first_frame (default: when context_frames is 0) */
  still?: boolean | null;
  /** video | png | latent */
  mode?: string | null;
  /** exposure_ref: the carried pictures scaled to its brightness (an anchor, or true for from) */
  color_reanchor?: unknown | null;
  /** other keys */
  [key: string]: unknown;
}

/** A queue cleared */
export interface Cleared {
  cleared: number;
}

/** A clip's record: a queue item, the running job, or what /api/gen and /api/clip answer - every generate key as the studio settled it, and what starting it added (the engine's id, the clip's name, when it started, its energy) */
export interface Clip {
  prompt?: string | null;
  label?: string | null;
  /** the clip: h3_YYYYMMDD_HHMMSS (once it starts) */
  name?: string | null;
  /** the engine's job id */
  id?: string | null;
  /** unix seconds */
  started?: number | null;
  project?: string | null;
  seconds?: number | null;
  energy_wh?: number | null;
  reentrant_id?: string | null;
  batch?: string | null;
  frames?: number | null;
  steps?: number | null;
  seed?: number | null;
  /** teacher | student */
  te?: string | null;
  engine?: string | null;
  width?: number | null;
  height?: number | null;
  /** an anchor or a still's file */
  first_frame?: string | null;
  camera?: string | null;
  upscale?: number | null;
  /** "path:strength" */
  loras?: string[] | null;
  /** /api/clip: the words spoken, and queued, held or running */
  dialogue?: string | null;
  state?: ClipState | null;
  /** other keys */
  [key: string]: unknown;
}

/** A finished clip's record (`<clip>.json`): the job as made, its stages' times, frames, wall time, energy */
export interface ClipRecord {
  job: Clip;
  times?: Record<string, number> | null;
  frames?: number | null;
  wall?: number | null;
  energy_wh?: number | null;
  /** other keys */
  [key: string]: unknown;
}

/** A clip asked for (video.generate's body, and the legacy /api/gen's): the studio checks each value and its range */
export interface ClipRequest {
  prompt: string;
  /** 1-15.1, snapped up to 17k + 5 frames; the model is trained on 124-362 frames at 24 fps */
  seconds?: number | null;
  /** instead of seconds: exactly 17k + 5 (22-362), else 400 naming the nearest */
  frames?: number | null;
  /** idempotent submit: a clip of this id queued, running or made is answered instead */
  reentrant_id?: string | null;
  chain?: Chain | null;
  /** 1-40; below 8 only with a turbo LoRA */
  steps?: number | null;
  seed?: number | null;
  /** teacher | student (the text encoder) */
  te?: unknown | null;
  /** "Name NN/MM: ..." - the NN drives edit order */
  label?: unknown | null;
  /** 256-1344, multiples of 32, width * height <= 1032192 */
  width?: number | null;
  height?: number | null;
  /** the denoiser (engines' quant): INT8 (default), Q6_K, Q4_K_M; REF2VA is chosen by itself for ref_images / ref_videos */
  engine?: string | null;
  /** png | video | latent | none */
  chain_mode?: string | null;
  /** an anchor (prev, prev_cam, first, first_cam: the series' previous clip or hub, *_cam the same camera only) or a still in the clips directory */
  first_frame?: unknown | null;
  last_frame?: unknown | null;
  exposure_ref?: unknown | null;
  first_audio?: unknown | null;
  first_audio_s?: unknown | null;
  /** a driving soundtrack (a song: a sound file in the clips directory, video.upload): the clip's length of it from soundtrack_start is pinned under the whole clip as an audio keyframe, and the picture is made to it (a singer's mouth to the singing); the clip carries the file's own sound. Not with first_audio (a chain's sound is off) */
  soundtrack?: unknown | null;
  /** seconds into the soundtrack at the clip's first frame (default 0); a chain's next clip starts where its first carried frame is in the song */
  soundtrack_start?: number | null;
  /** harmful here: decodes as visible confetti */
  cond_noise_aug?: unknown | null;
  camera?: unknown | null;
  /** latent upscale at decode, 1.5 = free resolution */
  upscale?: unknown | null;
  /** esrgan-general (default) | esrgan-anime | latent */
  upscaler?: unknown | null;
  /** "path:strength" */
  loras?: unknown[] | null;
  /** at most 3; voices to speak in: <Audio 1>, <Audio 2> ... (files in the clips directory) */
  ref_audios?: unknown[] | null;
  /** at most 9 (Ref2VA), named in the prompt as <Picture i> */
  ref_images?: unknown[] | null;
  /** at most 3 (Ref2VA), named as <Video k> */
  ref_videos?: unknown[] | null;
  /** match | max */
  ref_image_size?: unknown | null;
  ref_video_sound?: unknown | null;
  /** the keyframe pictures shown to the text encoder too (default on) */
  te_pictures?: unknown | null;
  /** motion guide: "<anchor or file>[:frames[:at]]" - the last frames of a clip as one moving keyframe */
  guide_clip?: unknown | null;
  /** flow shifts (12, 3) */
  shift_video?: unknown | null;
  shift_audio?: unknown | null;
  /** masked run: a clip whose latents are kept outside the regenerated part */
  source?: unknown | null;
  /** "from-to" seconds to regenerate; a source shorter than the clip is extended */
  regen?: unknown | null;
  /** "x0,y0,x1,y1" pixels: regenerate only inside */
  regen_box?: unknown | null;
  /** the Fun ControlNet: a control video (canny / depth / HED / MLSD / pose frames), a mask (white: regenerate) over a source video; files in the clips directory */
  control_video?: unknown | null;
  control_mask?: unknown | null;
  control_source?: unknown | null;
  control_strength?: number | null;
  control_start?: number | null;
  control_end?: number | null;
  /** ComfyUI's sampler and schedule names (none: Euler on the shifted schedule) */
  sampler?: string | null;
  schedule?: string | null;
  project?: string | null;
  batch?: string | null;
  /** busy without it: 409 busy */
  queue?: boolean | null;
  /** -9..9: a queued clip goes ahead of lower ones */
  priority?: number | null;
  /** other keys */
  [key: string]: unknown;
}

