/** A route's failure: the words its body's `error` said, and the body. */
export class RouteError extends Error {
  constructor(message: string, readonly body: unknown) {
    super(message);
  }
}

function runtime(base: string, fetcher: typeof fetch) {
  const words = (e: any): string => (typeof e === "string" ? e : (e?.message ?? JSON.stringify(e)));
  const read = async (res: Response, u: string, ownError: boolean): Promise<any> => {
    const text = await res.text();
    let v: any = null;
    try {
      v = text ? JSON.parse(text) : null;
    } catch {
      throw new RouteError(`${u}: the answer is not JSON (HTTP ${res.status})`, text);
    }
    const failed = v !== null && typeof v === "object" && !Array.isArray(v) && v.error != null && (!ownError || v.ok === false);
    if (failed) throw new RouteError(words(v.error), v);
    return v;
  };
  return {
    url(path: string, req: object, query: boolean): string {
      const fields = req as Record<string, unknown>;
      const used = new Set<string>();
      let p = path.replace(/\{([^}]+)\}/g, (_, k: string) => {
        used.add(k);
        return encodeURIComponent(String(fields[k] ?? ""));
      });
      if (query) {
        const q = new URLSearchParams();
        for (const [k, v] of Object.entries(fields)) {
          if (used.has(k) || v === undefined || v === null) continue;
          for (const x of Array.isArray(v) ? v : [v]) q.append(k, String(x));
        }
        const s = q.toString();
        if (s) p += `?${s}`;
      }
      return base + p.slice(1);
    },
    async json(method: string, u: string, body?: BodyInit, type?: string, ownError = false): Promise<any> {
      const res = await fetcher(u, { method, body, headers: type ? { "content-type": type } : undefined });
      return read(res, u, ownError);
    },
    async either(method: string, u: string, body: unknown, ownError = false): Promise<any> {
      const form = body instanceof FormData;
      const res = await fetcher(u, { method, body: form ? body : JSON.stringify(body), headers: form ? undefined : { "content-type": "application/json" } });
      return read(res, u, ownError);
    },
    async blob(method: string, u: string, body?: BodyInit, type?: string): Promise<any> {
      const res = await fetcher(u, { method, body, headers: type ? { "content-type": type } : undefined });
      if ((res.headers.get("content-type") ?? "").startsWith("application/json")) return read(res, u, false);
      return res.blob();
    },
  };
}

export function routes(base = "", fetcher: typeof fetch = (u, i) => fetch(u, i)) {
  const r = runtime(base, fetcher);
  return {
    /**
     * The card's telemetry
     * @route GET /api/gpu
     * @tags page
     */
    gpu: (): Promise<Gpu> => r.json("GET", r.url("/api/gpu", {}, true), undefined, undefined, true),
    /**
     * The rates of the last clips made, what the queue will take, the disk, the running project's totals
     * @route GET /api/summary
     * @tags page
     */
    summary: (): Promise<Summary> => r.json("GET", r.url("/api/summary", {}, true), undefined, undefined, false),
    /**
     * The denoisers the engine has
     * @route GET /api/engines
     * @tags page
     */
    engines: (): Promise<Engines> => r.json("GET", r.url("/api/engines", {}, true), undefined, undefined, false),
    /**
     * The canvases offered
     * @route GET /api/canvases
     * @tags page
     */
    canvases: (): Promise<Canvases> => r.json("GET", r.url("/api/canvases", {}, true), undefined, undefined, false),
    /**
     * The canvas table's model: the denoisers, canvases, defaults, what a card holds and each GPU's measured step cost
     * @route GET /api/plan
     * @tags page
     */
    plan: (): Promise<Plan> => r.json("GET", r.url("/api/plan", {}, true), undefined, undefined, false),
    /**
     * The studio now (as POST /rpc/status)
     * @route GET /api/status
     * @tags page
     */
    status: (): Promise<Status> => r.json("GET", r.url("/api/status", {}, true), undefined, undefined, true),
    /**
     * Every finished clip, newest first
     * @route GET /api/list
     * @tags page
     */
    list: (): Promise<ListRow[]> => r.json("GET", r.url("/api/list", {}, true), undefined, undefined, false),
    /**
     * The prompt templates
     * @route GET /api/templates
     * @tags page
     */
    templates: (): Promise<Template[]> => r.json("GET", r.url("/api/templates", {}, true), undefined, undefined, false),
    /**
     * The joined films, newest first
     * @route GET /api/films
     * @tags page
     */
    films: (): Promise<Film[]> => r.json("GET", r.url("/api/films", {}, true), undefined, undefined, false),
    /**
     * The films being joined, and joined since the studio started
     * @route GET /api/join
     * @tags page
     */
    joins: (): Promise<Joins> => r.json("GET", r.url("/api/join", {}, true), undefined, undefined, false),
    /**
     * A project's clips in edit order: finished (the newest retry of each number), running, held, queued
     * @route GET /api/timeline
     * @tags page
     */
    timeline: (req: ProjectRef = {}): Promise<Timeline> => r.json("GET", r.url("/api/timeline", req, true), undefined, undefined, false),
    /**
     * The RPC layer's TypeScript (its types and an rpc() helper)
     * @route GET /api/types.ts
     * @tags page
     * @produces application/typescript
     */
    typesTs: (): string => r.url("/api/types.ts", {}, true),
    /**
     * A project as a portable scene file (pretty JSON)
     * @route GET /api/scene
     * @tags page
     */
    scene: (req: ProjectRef = {}): Promise<Scene> => r.json("GET", r.url("/api/scene", req, true), undefined, undefined, false),
    /**
     * A clip not made yet, by its label: running, held or queued, with the words it speaks
     * @route GET /api/clip
     * @tags page
     */
    clip: (req: LabelRef = {}): Promise<Clip> => r.json("GET", r.url("/api/clip", req, true), undefined, undefined, false),
    /**
     * A finished clip's record
     * @route GET /api/job/{name}
     * @tags page
     */
    job: (req: FileName): Promise<ClipRecord> => r.json("GET", r.url("/api/job/{name}", req, true), undefined, undefined, false),
    /**
     * A finished clip's 240-pixel still, 5 s in (made once, then kept)
     * @route GET /thumb/{name}
     * @tags files
     * @produces image/webp
     */
    thumb: (req: FileName): string => r.url("/thumb/{name}", req, true),
    /**
     * A clip (mp4, in byte ranges: the player seeks), or its preview while it samples (<clip>.preview.png) and its last frame (<clip>.last.png)
     * @route GET /out/{name}
     * @tags files
     * @produces video/mp4, image/png
     * @ranges
     */
    out: (req: FileName): string => r.url("/out/{name}", req, true),
    /**
     * A reference picture, clip or sound, kept beside the clips (references are named by file there): the body is the file
     * @route POST /api/upload
     * @tags page
     * @body bytes
     */
    upload: (data: Blob | ArrayBuffer | Uint8Array, req: UploadName = {}): Promise<Uploaded> => r.json("POST", r.url("/api/upload", req, true), data, undefined, false),
    /**
     * Holds the queue, a project or a batch (on), or releases it
     * @route POST /api/queue/pause
     * @tags page
     */
    queuePause: (req: HoldReq = {}): Promise<Done> => r.json("POST", r.url("/api/queue/pause", req, false), JSON.stringify(req), "application/json", false),
    /**
     * Joins a project's finished clips, in timeline order, into one film (in the background: GET /api/join follows it)
     * @route POST /api/join
     * @tags page
     */
    join: (req: ProjectRef = {}): Promise<JoinStarted> => r.json("POST", r.url("/api/join", req, false), JSON.stringify(req), "application/json", false),
    /**
     * Empties the queue
     * @route POST /api/queue/clear
     * @tags page
     */
    queueClear: (req: Record<string, never> = {}): Promise<Cleared> => r.json("POST", r.url("/api/queue/clear", {}, false), JSON.stringify(req), "application/json", false),
    /**
     * Queues a scene file's clips (all or nothing), as a project, held or not
     * @route POST /api/scene/import
     * @tags page
     */
    sceneImport: (req: SceneImport = {}): Promise<Imported> => r.json("POST", r.url("/api/scene/import", req, false), JSON.stringify(req), "application/json", false),
    /**
     * The oldest route: a clip made or queued, its seconds and steps clamped (the RPC refuses them instead) and an unknown te read as teacher; answers the queue position and label, or the job started
     * @route POST /api/gen
     * @tags page
     */
    gen: (req: ClipRequest): Promise<Clip> => r.json("POST", r.url("/api/gen", req, false), JSON.stringify(req), "application/json", false),
  };
}
